<script>
document.addEventListener('click', function (e) {
  var b = e.target.closest('[data-tk-dis]'); if (!b) return;
  var f = b.closest('form'); f.querySelector('[data-tk-reason]').value = b.getAttribute('data-tk-dis');
  f.querySelectorAll('[data-tk-dis]').forEach(function (x) { x.classList.toggle('on', x === b); });
});
document.addEventListener('sl:done', function (e) {
  var f = e.target; if (!f.matches || !f.matches('form[action$="add_courier_tracking.php"]')) return;
  var j = e.detail || {};
  if (j.success) { SL.toast((j.messages || ['Event saved']).join(' ')); setTimeout(function () { location.reload(); }, 400); }
  else if (j.errors) { var m = Object.keys(j.errors).map(function (k) { return j.errors[k]; }).join(' '); if (m) SL.toast(m, true); }
}, true); // sl:done does not bubble: listen in the capture phase
</script>
